from pathlib import Path
import json,hashlib,shutil,html
from PIL import Image,ImageOps,ImageDraw
A=Path(__file__).resolve().parent;R=A.parents[2]
D=R/'documentation/creatures/caracol-pneu-chart-v1';D.mkdir(parents=True,exist_ok=True)
G=Path('C:/Users/user/.codex/generated_images/01a17924-9eaf-7951-8ded-c6920198ad3f')
items=json.loads((A/'geracao.json').read_text(encoding='utf-8'))
refs={1:['espirrodante/concept-v1/concept.png: identidade e acabamento'],2:['caracol-pneu-baby/concept-v1/concept.png: origem','espirrodante/concept-v1/concept.png: destino'],3:['caracol-pneu-child/concept-v1/concept.png: origem','espirrodante/concept-v1/concept.png: destino'],4:['../gambalhote/gambalhote-adult/concept-v2/concept.png: acabamento apenas']}
nodes=[]
for item in items:
    F=A/item['id']/'concept-v1';F.mkdir(parents=True,exist_ok=True)
    shutil.copy2(G/item['source'],F/'concept.png')
    (F/'prompt.txt').write_text(item['prompt'],encoding='utf-8')
    (F/'brief.md').write_text('# '+item['name']+' — caracol-pneu\n\nDefinido pelo autor: evo line de caracol + pneu de carro, mantendo estilo. Não foi solicitado cavaleiro.\n\nProposta: '+item['story']+'\n\nHerança: corpo ocre, pé marfim, aro carvão/azul-marinho, marcas lima e nós roxos. Espiral é membrana tensionada, varetas dão suporte; banda de rodagem inspira painéis dobráveis. Aderir → deslizar → embalar → rolar é narrativa de maturidade, não regra implementada. Limitação proposta: depende de espaço para abrir os painéis e perde alcance de manobra em passagens estreitas.\n\nMovimento da roda é fantasia a resolver em estudo de ação; a concha e o pé real não funcionam como eixo de carro. A rabiola porta uma única identidade almática. Nomes, elemento, mecânicas, habilidades e obtenção não definidos.\n',encoding='utf-8')
    (F/'revisao.md').write_text('# Conferência\n\n'+item['review']+'\n\nProposta sem aprovação. Traço limpo com planos amplos; algumas transições suaves claras permanecem, sem textura realista. Concept não é pixel art técnico, recorte, rig ou animação. Sem integração.\n',encoding='utf-8')
    im=Image.open(F/'concept.png')
    (F/'manifest.json').write_text(json.dumps(dict(tool='image_gen.imagegen',source=item['source'],sha256=hashlib.sha256((F/'concept.png').read_bytes()).hexdigest(),dimensions=list(im.size),mode=im.mode,alpha='A' in im.getbands(),prompt='prompt.txt',own_reference_inputs=refs[item['stage']],reference_paths_relative_to='art/creatures/caracol-pneu-family-v1',decision_status='proposed',production_status='concept',integration_status='not_integrated'),indent=2,ensure_ascii=False),encoding='utf-8')
    rel='../../../art/creatures/caracol-pneu-family-v1/'+item['id']+'/concept-v1/'
    nodes.append(dict(id=item['id'],name=item['name'],kind='stage',stage=item['stage'],maturity=['Bebê','Criança','Jovem','Adulto'][item['stage']-1],identity=item['story'],story=item['story'],decision_status='proposed',production_status='concept',art=rel+'concept.png',brief=rel+'brief.md'))
edges=[dict(**{'from':nodes[i]['id'],'to':nodes[i+1]['id']},kind='reweaving',reason=nodes[i+1]['story'],decision_status='proposed') for i in range(3)]
(D/'chart.json').write_text(json.dumps(dict(family_id='caracol-pneu',scope='Quatro concepts propostos; sem integração ou validação mecânica.',nodes=nodes,edges=edges),indent=2,ensure_ascii=False),encoding='utf-8')
sheet=Image.new('RGB',(2400,800),'white')
for i,n in enumerate(nodes):
    im=ImageOps.contain(Image.open(D/n['art']).convert('RGB'),(580,710));sheet.paste(im,(600*i+(600-im.width)//2,60+(710-im.height)//2))
    ImageDraw.Draw(sheet).text((600*i+18,20),['Bebe','Crianca','Jovem','Adulto'][i]+' / proposta',fill='black')
sheet.save(D/'familia.png')
(D/'CHART.md').write_text('# Caracol + pneu — linha proposta\n\nBebê de concha pequena → criança de pé alongado → jovem de casco inclinado e duas abas abertas → adulto Espirrodante, roda-vela vertical (nome proposto). Nomes e regras abertos.\n\n45% criatura /45% pipa /10% acabamento 2D é direção, não medida de pixels. Concha é membrana, aro é proteção e varetas/nós explicam a construção. Não é caracol comum transportando um pneu solto ou um carro com rosto. Um pé contínuo e dois pares de tentáculos mantêm identidade de gastrópode.\n\nPesquisa em ESTUDO.md. Criança preserva anatomia clássica; jovem muda orientação da concha; adulto amplia painel e postura. A imagem não demonstra rotação funcional: o encaixe corpo/concha precisará de estudo antes de rig. Sem integração.\n',encoding='utf-8')
(D/'ESTUDO.md').write_text('# Pesquisa e tradução visual\n\nFontes primárias consultadas em 04/11/2026, por texto; nenhuma imagem externa usada na geração.\n\n[Field of Mars EEC — Snail fact sheet](https://fieldofmar-e.schools.nsw.gov.au/fact-sheets/invertebrates/snail-fact-sheet): corpo mole, pé muscular largo, tentáculos e concha protetora. Aplicação: preservar um único pé contínuo e dois tentáculos superiores com olhos mais dois inferiores; retração/proteção inspira a primeira forma. A evolução desenhada não corresponde ao crescimento zoológico real.\n\n[Michelin — Tyre tread](https://www.michelin.com.au/auto/advice/change-tyres/tyre-tread): ranhuras e área de contato participam de tração e escoamento. Aplicação: poucas marcas largas de rodagem e painéis que se abrem, em vez de textura ou marca de fabricante. Não transferir valores ou orientações de manutenção para regras de jogo.\n\nSíntese fantástica: aro flexível protege espiral de papel; varetas curvas sustentam membrana; abas da banda captam vento. Corpo ocre e casco carvão/lima contrastam, nós/rabiola roxos ligam a família. Jovem baixo e adulto vertical criam mudança de função e silhueta. Movimento rotativo de um casco ligado a corpo vivo ainda exige solução visual; concept não comprova mecanismo real.\n',encoding='utf-8')
(D/'fontes.json').write_text(json.dumps([dict(url='https://fieldofmar-e.schools.nsw.gov.au/fact-sheets/invertebrates/snail-fact-sheet',title='Snail fact sheet',entity='Field of Mars Environmental Education Centre / NSW Education',access='2026-11-04',fact='Caracóis têm corpo mole, concha protetora, tentáculos e pé muscular largo.',application='Um pé contínuo, dois pares de tentáculos e proteção; movimento de pneu é fantasia.'),dict(url='https://www.michelin.com.au/auto/advice/change-tyres/tyre-tread',title='Understanding your car’s tyre tread',entity='Michelin',access='2026-11-04',fact='Sulcos e banda de rodagem se relacionam com contato, tração e dispersão de água.',application='Poucos blocos de rodagem e painéis móveis de pipa; sem marca ou números técnicos.')],ensure_ascii=False,indent=2),encoding='utf-8')
cards=''.join('<article><h2>'+html.escape(n['name'])+'</h2><img src="'+n['art']+'" alt="'+html.escape(n['identity'])+'"><p>'+html.escape(n['story'])+'</p><a href="'+n['brief']+'">Brief</a></article>' for n in nodes)
(D/'index.html').write_text('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Caracol-pneu</title><style>body{font:18px system-ui;background:#f5f3df;color:#242438;margin:40px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px}article{background:white;padding:22px;border:1px solid #b7bca1}img{width:100%;height:390px;object-fit:contain}a:focus{outline:3px solid #782796}</style><h1>Caracol-pneu: linha evolutiva</h1><p>Concepts propostos. <a href="ESTUDO.md">Pesquisa e construção</a></p><main>'+cards+'</main></html>',encoding='utf-8')
(A/'DECISOES.md').write_text('# Caracol-pneu\n\nPedido: evo line de caracol + pneu de carro. Quatro concepts em proposta. Adulto Espirrodante é nome proposto. Sem aprovação, integração ou regras de movimento implementadas.\n',encoding='utf-8')
print(D)
